# Recompute each overlay row's section from the image section table.
# Fails if any row other than the three inherited call-site bytes is in
# section 6 or 7, or if the stored section label disagrees.
# Do not edit this file after it has run.
import csv
import json
import struct
from pathlib import Path

ROOT = Path('.')
IMAGE = ROOT / 'inputs/00_0100_50000020.decoded.bin'
SRC = ROOT / 'work/out/overlay-changed-bytes.csv'
OUT = ROOT / 'work/out/section-rows-t6.json'

BASE_PAGE_OFFSET = 0x020
FLASH_VIEW = 0x50000000
SECTION_ROW = 12
SECTION_LOAD = [0xf1, 0xe3, 0x8f, 0xff, 0xe3, 0xcd, None, None, 0x00, 0x00, 0x82, 0x8c, 0x14, 0xf9, 0x14, 0x0c, 0xf1, 0xe2, 0xfc, 0xd2]
SECTION_SWITCH = [0x04, 0xa0, 0x01, 0xc0, None, 0xa0, None, 0xc1, None, 0x28, 0xff, 0x54, 0xfc, 0xdc, None, None, None, None, 0xf3, 0x80, 0xf0, 0xf4]
PERMITTED = {0x610bf5e3, 0x610bf5e4, 0x610bf5e5}
MARK = 'section 7, EMULATOR-ONLY runtime call-site patch (inherited central-edge)'


def u32(buf, off):
    return struct.unpack_from('<I', buf, off)[0]


def cached(addr):
    if 0xA0000000 <= addr < 0xC0000000:
        return (addr - 0x40000000) & 0xFFFFFFFF
    return addr & 0xFFFFFFFF


def bytes_at(buf, off, pat):
    return all(p is None or buf[off + i] == p for i, p in enumerate(pat))


def one_at(buf, pat):
    hits = []
    start = 0
    while True:
        o = buf.find(bytes([pat[0]]), start)
        if o < 0 or o + len(pat) > len(buf):
            break
        if bytes_at(buf, o, pat):
            hits.append(o)
        start = o + 1
    if len(hits) != 1:
        raise SystemExit(f'pattern hits {len(hits)}')
    return hits[0]


def call_at(buf, o):
    op = buf[o]
    if op == 0xdd:
        return o + struct.unpack_from('<i', buf, o + 1)[0]
    if op == 0xfc and buf[o + 1] == 0xff:
        return o + struct.unpack_from('<i', buf, o + 2)[0]
    raise SystemExit(f'not a call at {o:#x}')


def image_base(buf):
    hits = []
    for o in range(min(0x400, len(buf) - 8) + 1):
        if buf[o] == 0xfc and buf[o + 1] == 0xdc and buf[o + 6] == 0xf0 and buf[o + 7] == 0xf4:
            hits.append(o)
    if len(hits) != 1:
        raise SystemExit(f'image base jumps {len(hits)}')
    target = u32(buf, hits[0] + 2)
    return (target & ~0xfff) | BASE_PAGE_OFFSET


def main():
    image = IMAGE.read_bytes()
    base = image_base(image)
    at = one_at(image, SECTION_LOAD)
    table = u32(image, at + 20)
    switch_off = call_at(image, at + 5)
    if not bytes_at(image, switch_off, SECTION_SWITCH):
        raise SystemExit('section switch mismatch')
    count = image[switch_off + 6]
    jt = u32(image, switch_off + 14) - base
    ends = []
    for n in range(1, count + 1):
        case_off = u32(image, jt + 4 * (n - 1)) - base
        if image[case_off] != 0xfc or image[case_off + 1] != 0xcc:
            raise SystemExit(f'section {n} case is not mov')
        ends.append(u32(image, case_off + 2))
    sections = []
    for i, end in enumerate(ends):
        row = (table - base) + SECTION_ROW * i
        start = u32(image, row)
        sections.append({'n': i + 1, 'start': start, 'end': end})
    problems = []
    counts = {}
    found = set()
    with SRC.open(encoding='utf-8', newline='') as f:
        rows = list(csv.DictReader(f))
    for rec in rows:
        addr = int(rec['runtime_address'], 16)
        off = int(rec['component_offset'], 16)
        stock = int(rec['stock_byte'], 16)
        if image[off] != stock:
            problems.append(f'stock mismatch {addr:#x}')
        c = cached(addr)
        sec = next((s for s in sections if s['start'] <= c < s['end']), None)
        if sec is None:
            problems.append(f'{addr:#x} in no section')
            continue
        counts[sec['n']] = counts.get(sec['n'], 0) + 1
        label = rec.get('section', '')
        if addr in PERMITTED:
            found.add(addr)
            if sec['n'] != 7 or label != MARK:
                problems.append(f'call site {addr:#x} section {sec["n"]} label {label!r}')
        else:
            if sec['n'] in (6, 7):
                problems.append(f'{addr:#x} is section {sec["n"]}')
            if label != str(sec['n']):
                problems.append(f'{addr:#x} label {label!r} computed {sec["n"]}')
    missing = sorted(PERMITTED - found)
    if missing:
        problems.append('missing call site ' + ' '.join(hex(a) for a in missing))
    profile = sum(1 for r in rows if r['source'] == 'profile-read')
    report = {
        'ok': not problems,
        'rows': len(rows),
        'counts': counts,
        'profile_read_rows': profile,
        'problems': problems[:20],
        'base': hex(base),
    }
    OUT.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    print(json.dumps(report))
    if problems:
        raise SystemExit(1)


if __name__ == '__main__':
    main()
